      );
      actions.push(
        <Tooltip title="停止仿真" key="stop">
          <Button
            danger
            icon={<StopOutlined />}
            onClick={() => onStop(id)}
          >
            停止
          </Button>
        </Tooltip>
      );
    }

    actions.push(
      <Button key="view" onClick={() => onView(id)}>
        查看详情
      </Button>
    );

    return actions;
  };

  return (
    <Card
      title={
        <div className="flex justify-between items-center">
          <span className="font-semibold">{name}</span>
          <Badge
            color={statusColors[status]}
