// 使用示例
import { useCache } from '@utils/cacheManager';

function DataComponent() {
  const { data, loading, error } = useCache(
    'api-data-key',
    () => fetchApiData(),
    5 * 60 * 1000 // 5分钟TTL
  );

  if (loading) return <Spin />;
  if (error) return <div>Error: {error.message}</div>;

  return <div>{JSON.stringify(data)}</div>;
}
